import classNames from "classnames";
import { useCallback, useMemo, useState } from "react";

import {
    Classes,
    hideContextMenu,
    Menu,
    MenuDivider,
    MenuItem,
    showContextMenu,
} from "@blueprintjs/core";
import { Example, type ExampleProps } from "@blueprintjs/docs-theme";

export const ContextMenuPopoverExample: React.FC<ExampleProps> = props => {
    const [isOpen, setIsOpen] = useState(false);

    const handleClose = useCallback(() => {
        setIsOpen(false);
        hideContextMenu();
    }, []);

    const menu = useMemo(
        () => (
            <Menu>
                <MenuItem
                    icon="cross-circle"
                    intent="danger"
                    text="Click me to close"
                    onClick={handleClose}
                />
                <MenuItem icon="search-around" text="Search around..." />
                <MenuItem icon="search" text="Object viewer" />
                <MenuItem icon="graph-remove" text="Remove" />
                <MenuItem icon="group-objects" text="Group" />
                <MenuDivider />
                <MenuItem disabled={true} text="Clicked on node" />
            </Menu>
        ),
        [handleClose],
    );

    const handleContextMenu = useCallback(
        (event: React.MouseEvent<HTMLElement>) => {
            // ensure `preventDefault` is called just before `showContextMenu` and in the same event handler to prevent the
            // default browser context menu from hiding your custom context menu
            event.preventDefault();
            showContextMenu({
                content: menu,
                onClose: handleClose,
                targetOffset: {
                    left: event.clientX,
                    top: event.clientY,
                },
            });
            setIsOpen(true);
        },
        [handleClose, menu],
    );

    return (
        <Example className="docs-context-menu-example" options={false} {...props}>
            <div
                className={classNames("docs-context-menu-node", {
                    "docs-context-menu-open": isOpen,
                })}
                onContextMenu={handleContextMenu}
            />
            <span className={Classes.TEXT_MUTED}>Right-click on node to open.</span>
        </Example>
    );
};

