export function MenuItemExample(props: ExampleProps) {
    const [active, setActive] = useState(false);
    const [disabled, setDisabled] = useState(false);
    const [selected, setSelected] = useState<boolean | undefined>(undefined);
    const [intent, setIntent] = useState<Intent>("none");
    const [iconEnabled, setIconEnabled] = useState(true);
    const [submenuEnabled, setSubmenuEnabled] = useState(true);
    const [roleStructure, setRoleStructure] = useState<MenuItemProps["roleStructure"]>("menuitem");

    const handleRoleStructureChange = useCallback(
        (newValue: string) => setRoleStructure(newValue as MenuItemProps["roleStructure"]),
        [],
    );

    const isSelectable = roleStructure === "listoption";

    const options = (
        <>
            <H5>Props</H5>
            <Switch label="Active" checked={active} onChange={handleBooleanChange(setActive)} />
            <Switch
                label="Disabled"
                checked={disabled}
                onChange={handleBooleanChange(setDisabled)}
            />
            <Switch
                label="Enable icon"
                checked={iconEnabled}
                onChange={handleBooleanChange(setIconEnabled)}
            />
            <Switch
                label="Enable submenu"
                checked={submenuEnabled}
                onChange={handleBooleanChange(setSubmenuEnabled)}
            />
            <IntentSelect intent={intent} onChange={setIntent} />
            <FormGroup label="Role structure">
                <SegmentedControl
                    options={[{ value: "menuitem" }, { value: "listoption" }]}
                    onValueChange={handleRoleStructureChange}
                    size="small"
                    value={roleStructure}
                />
            </FormGroup>
            <PropCodeTooltip
                content={
                    isSelectable ? undefined : (
                        <>
                            <Code>selected</Code> prop has no effect when <br />
                            <Code>roleStructure="menuitem"</Code>
                        </>
                    )
                }
                disabled={isSelectable}
            >
                <BooleanOrUndefinedSelect
                    disabled={!isSelectable}
                    label="Selected"
                    value={selected}
                    onChange={setSelected}
                />
            </PropCodeTooltip>
        </>
    );

    return (
        <Example className="docs-menu-example" options={options} {...props}>
            <Menu className={Classes.ELEVATION_1}>
                <MenuItem
                    active={active}
                    disabled={disabled}
                    icon={iconEnabled ? "applications" : undefined}
                    intent={intent}
                    labelElement={submenuEnabled ? undefined : "⌘,"}
                    roleStructure={roleStructure}
                    selected={selected}
                    text="Applications"
                    children={
                        submenuEnabled ? (
                            <>
                                <MenuItem icon="add" text="Add new application" />
                                <MenuItem icon="remove" text="Remove application" />
                            </>
                        ) : undefined
                    }
                />
            </Menu>
        </Example>
    );
}

