                checked={readOnly}
                label="Read-only"
                onChange={handleBooleanChange(setReadOnly)}
            />
            <SizeSelect onChange={setSize} size={size} />
        </>
    );

    return (
        <Example options={options} {...props}>
            <InputGroup
                disabled={disabled}
                placeholder="Search..."
                readOnly={readOnly}
                size={size}
                type="search"
            />
        </Example>
    );
};

