import { useCallback, useReducer, useState } from "react";

import {
    Card,
    Classes,
    ContextMenu,
    H5,
    Icon,
    Intent,
    Switch,
    Tooltip,
    Tree,
    type TreeNodeInfo,
} from "@blueprintjs/core";
import { Example, type ExampleProps, handleBooleanChange } from "@blueprintjs/docs-theme";

type NodePath = number[];

type TreeAction =
    | { type: "SET_IS_EXPANDED"; payload: { path: NodePath; isExpanded: boolean } }
    | { type: "DESELECT_ALL" }
    | { type: "SET_IS_SELECTED"; payload: { path: NodePath; isSelected: boolean } };

function cloneTreeNodes(nodes: TreeNodeInfo[]): TreeNodeInfo[] {
    return nodes.map(node => ({
        ...node,
        childNodes: node.childNodes == null ? node.childNodes : cloneTreeNodes(node.childNodes),
    }));
}

function forEachNode(nodes: TreeNodeInfo[] | undefined, callback: (node: TreeNodeInfo) => void) {
    if (nodes === undefined) {
        return;
    }

    for (const node of nodes) {
        callback(node);
        forEachNode(node.childNodes, callback);
    }
}

function forNodeAtPath(
    nodes: TreeNodeInfo[],
    path: NodePath,
    callback: (node: TreeNodeInfo) => void,
) {
    callback(Tree.nodeFromPath(path, nodes));
}

function treeExampleReducer(state: TreeNodeInfo[], action: TreeAction) {
    switch (action.type) {
        case "DESELECT_ALL":
            const newState1 = cloneTreeNodes(state);
            forEachNode(newState1, node => (node.isSelected = false));
            return newState1;
        case "SET_IS_EXPANDED":
            const newState2 = cloneTreeNodes(state);
            forNodeAtPath(
                newState2,
                action.payload.path,
                node => (node.isExpanded = action.payload.isExpanded),
            );
            return newState2;
        case "SET_IS_SELECTED":
            const newState3 = cloneTreeNodes(state);
            forNodeAtPath(
                newState3,
                action.payload.path,
                node => (node.isSelected = action.payload.isSelected),
            );
            return newState3;
        default:
            return state;
    }
}

export const TreeExample: React.FC<ExampleProps> = props => {
    const [compact, setCompact] = useState(false);
    const [nodes, dispatch] = useReducer(treeExampleReducer, INITIAL_STATE);

    const handleNodeClick = useCallback(
        (node: TreeNodeInfo, nodePath: NodePath, e: React.MouseEvent<HTMLElement>) => {
            const originallySelected = node.isSelected;
            if (!e.shiftKey) {
                dispatch({ type: "DESELECT_ALL" });
            }
            dispatch({
                payload: {
                    isSelected: originallySelected == null ? true : !originallySelected,
                    path: nodePath,
                },
                type: "SET_IS_SELECTED",
            });
        },
        [],
    );

    const handleNodeCollapse = useCallback((_node: TreeNodeInfo, nodePath: NodePath) => {
        dispatch({
            payload: { isExpanded: false, path: nodePath },
            type: "SET_IS_EXPANDED",
        });
    }, []);

    const handleNodeExpand = useCallback((_node: TreeNodeInfo, nodePath: NodePath) => {
        dispatch({
            payload: { isExpanded: true, path: nodePath },
            type: "SET_IS_EXPANDED",
        });
    }, []);

    const options = (
        <>
            <H5>Props</H5>
            <Switch label="Compact" checked={compact} onChange={handleBooleanChange(setCompact)} />
        </>
    );

    return (
        <Example options={options} {...props}>
            <Card>
                <Tree
                    compact={compact}
                    contents={nodes}
                    onNodeClick={handleNodeClick}
                    onNodeCollapse={handleNodeCollapse}
                    onNodeExpand={handleNodeExpand}
                />
            </Card>
        </Example>
    );
};

