import { useCallback } from "react";

import { FormGroup, SegmentedControl } from "@blueprintjs/core";

export type Size = "small" | "regular" | "large";

const labels = ["Small", "Regular", "Large"];

export interface LegacySizeSelectProps {
    label?: string;
    size: Size;
    optionLabels?: [string, string, string];
    onChange: (size: Size) => void;
}

export const LegacySizeSelect: React.FC<LegacySizeSelectProps> = ({
    label = "Size",
    size,
    optionLabels = labels,
    onChange,
}) => {
    const handleChange = useCallback((value: string) => onChange(value as Size), [onChange]);

    return (
        <FormGroup label={label}>
            <SegmentedControl
                fill={true}
                options={[
                    { label: optionLabels[0], value: "small" },
                    { label: optionLabels[1], value: "regular" },
                    { label: optionLabels[2], value: "large" },
                ]}
                onValueChange={handleChange}
                size="small"
                value={size}
            />
        </FormGroup>
    );
};

export function getSizeProp(size: Size) {
    switch (size) {
        case "large":
            return { large: true };
        case "small":
            return { small: true };
        default:
            // regular is the default
            return {};
    }
}

